def dedup(items):
    seen = []
    out = []
    for it in items:
        duplicate = False
        for s in seen:
            try:
                same = (s == it) and (type(s) == type(it))
            except TypeError:
                same = False
            if same:
                duplicate = True
                break
        if not duplicate:
            seen.append(it)
            out.append(it)
    return out

